///////////////////////////////////////////////////////////////////////
// Byte order and rotation helpers
///////////////////////////////////////////////////////////////////////
static inline uint32_t rol32(uint32_t x, unsigned n) { return (x << n) | (x >> (32u - n)); }
static inline uint32_t ror32(uint32_t x, unsigned n) { return (x >> n) | (x << (32u - n)); }
static inline uint64_t ror64(uint64_t x, unsigned n) { return (x >> n) | (x << (64u - n)); }

static inline uint32_t load_le32(const uint8_t *p) {
  return (uint32_t)p[0] | ((uint32_t)p[1] << 8) | ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24);
}
static inline uint32_t load_be32(const uint8_t *p) {
  return ((uint32_t)p[0] << 24) | ((uint32_t)p[1] << 16) | ((uint32_t)p[2] << 8) | (uint32_t)p[3];
}
static inline uint64_t load_be64(const uint8_t *p) {
  return ((uint64_t)load_be32(p) << 32) | load_be32(p + 4);
}
static inline void store_le32(uint8_t *p, uint32_t v) {
  p[0] = (uint8_t)v; p[1] = (uint8_t)(v >> 8); p[2] = (uint8_t)(v >> 16); p[3] = (uint8_t)(v >> 24);
}
static inline void store_be32(uint8_t *p, uint32_t v) {
  p[0] = (uint8_t)(v >> 24); p[1] = (uint8_t)(v >> 16); p[2] = (uint8_t)(v >> 8); p[3] = (uint8_t)v;
}
static inline void store_le64(uint8_t *p, uint64_t v) {
  store_le32(p, (uint32_t)v); store_le32(p + 4, (uint32_t)(v >> 32));
}
static inline void store_be64(uint8_t *p, uint64_t v) {
  store_be32(p, (uint32_t)(v >> 32)); store_be32(p + 4, (uint32_t)v);
}

///////////////////////////////////////////////////////////////////////
// Block functions
///////////////////////////////////////////////////////////////////////
static void md5_block(uint32_t *s, const uint8_t *p) {
  uint32_t m[16];
  for (int i = 0; i < 16; i++) m[i] = load_le32(p + 4 * i);
  uint32_t a = s[0], b = s[1], c = s[2], d = s[3];
  for (unsigned i = 0; i < 64; i++) {
    uint32_t f;
    unsigned g;
    if (i < 16)      { f = (b & c) | (~b & d); g = i; }
    else if (i < 32) { f = (d & b) | (~d & c); g = (5 * i + 1) & 15; }
    else if (i < 48) { f = b ^ c ^ d;          g = (3 * i + 5) & 15; }
    else             { f = c ^ (b | ~d);       g = (7 * i) & 15; }
    uint32_t tmp = d;
    d = c;
    c = b;
    b = b + rol32(a + f + md5_k[i] + m[g], md5_shift[i]);
    a = tmp;
  }
  s[0] += a; s[1] += b; s[2] += c; s[3] += d;
}

static void sha1_block(uint32_t *s, const uint8_t *p) {
  uint32_t w[80];
  for (int i = 0; i < 16; i++) w[i] = load_be32(p + 4 * i);
  for (int i = 16; i < 80; i++) w[i] = rol32(w[i - 3] ^ w[i - 8] ^ w[i - 14] ^ w[i - 16], 1);
  uint32_t a = s[0], b = s[1], c = s[2], d = s[3], e = s[4];
  for (int i = 0; i < 80; i++) {
    uint32_t f, k;
    if (i < 20)      { f = (b & c) | (~b & d);          k = 0x5a827999u; }
    else if (i < 40) { f = b ^ c ^ d;                   k = 0x6ed9eba1u; }
    else if (i < 60) { f = (b & c) | (b & d) | (c & d); k = 0x8f1bbcdcu; }
    else             { f = b ^ c ^ d;                   k = 0xca62c1d6u; }
    uint32_t tmp = rol32(a, 5) + f + e + k + w[i];
    e = d; d = c; c = rol32(b, 30); b = a; a = tmp;
  }
  s[0] += a; s[1] += b; s[2] += c; s[3] += d; s[4] += e;
}

static void sha256_block(uint32_t *s, const uint8_t *p) {
  uint32_t w[64];
  for (int i = 0; i < 16; i++) w[i] = load_be32(p + 4 * i);
  for (int i = 16; i < 64; i++) {
    uint32_t s0 = ror32(w[i - 15], 7) ^ ror32(w[i - 15], 18) ^ (w[i - 15] >> 3);
    uint32_t s1 = ror32(w[i - 2], 17) ^ ror32(w[i - 2], 19) ^ (w[i - 2] >> 10);
    w[i] = w[i - 16] + s0 + w[i - 7] + s1;
  }
  uint32_t a = s[0], b = s[1], c = s[2], d = s[3], e = s[4], f = s[5], g = s[6], h = s[7];
  for (int i = 0; i < 64; i++) {
    uint32_t S1 = ror32(e, 6) ^ ror32(e, 11) ^ ror32(e, 25);
    uint32_t ch = (e & f) ^ (~e & g);
    uint32_t t1 = h + S1 + ch + sha256_k[i] + w[i];
    uint32_t S0 = ror32(a, 2) ^ ror32(a, 13) ^ ror32(a, 22);
    uint32_t mj = (a & b) ^ (a & c) ^ (b & c);
    uint32_t t2 = S0 + mj;
    h = g; g = f; f = e; e = d + t1; d = c; c = b; b = a; a = t1 + t2;
  }
  s[0] += a; s[1] += b; s[2] += c; s[3] += d; s[4] += e; s[5] += f; s[6] += g; s[7] += h;
}

static void sha512_block(uint64_t *s, const uint8_t *p) {
  uint64_t w[80];
  for (int i = 0; i < 16; i++) w[i] = load_be64(p + 8 * i);
  for (int i = 16; i < 80; i++) {
    uint64_t s0 = ror64(w[i - 15], 1) ^ ror64(w[i - 15], 8) ^ (w[i - 15] >> 7);
    uint64_t s1 = ror64(w[i - 2], 19) ^ ror64(w[i - 2], 61) ^ (w[i - 2] >> 6);
    w[i] = w[i - 16] + s0 + w[i - 7] + s1;
  }
  uint64_t a = s[0], b = s[1], c = s[2], d = s[3], e = s[4], f = s[5], g = s[6], h = s[7];
  for (int i = 0; i < 80; i++) {
    uint64_t S1 = ror64(e, 14) ^ ror64(e, 18) ^ ror64(e, 41);
    uint64_t ch = (e & f) ^ (~e & g);
    uint64_t t1 = h + S1 + ch + sha512_k[i] + w[i];
    uint64_t S0 = ror64(a, 28) ^ ror64(a, 34) ^ ror64(a, 39);
    uint64_t mj = (a & b) ^ (a & c) ^ (b & c);
    uint64_t t2 = S0 + mj;
    h = g; g = f; f = e; e = d + t1; d = c; c = b; b = a; a = t1 + t2;
  }
  s[0] += a; s[1] += b; s[2] += c; s[3] += d; s[4] += e; s[5] += f; s[6] += g; s[7] += h;
}

static void hash_block(eos_hash_ctx_t *ctx, const uint8_t *p) {
  switch (ctx->alg) {
    case EOS_HASH_MD5:    md5_block(ctx->state.w32, p); break;
    case EOS_HASH_SHA1:   sha1_block(ctx->state.w32, p); break;
    case EOS_HASH_SHA224:
    case EOS_HASH_SHA256: sha256_block(ctx->state.w32, p); break;
    case EOS_HASH_SHA384:
    case EOS_HASH_SHA512: sha512_block(ctx->state.w64, p); break;
    default: break;
  }
}

///////////////////////////////////////////////////////////////////////
// Public API
///////////////////////////////////////////////////////////////////////
size_t eos_hash_digest_size(eos_hash_alg_t alg) {
  switch (alg) {
    case EOS_HASH_MD5:    return 16;
    case EOS_HASH_SHA1:   return 20;
    case EOS_HASH_SHA224: return 28;
    case EOS_HASH_SHA256: return 32;
    case EOS_HASH_SHA384: return 48;
    case EOS_HASH_SHA512: return 64;
    default: return 0;
  }
}

const char *eos_hash_name(eos_hash_alg_t alg) {
  switch (alg) {
    case EOS_HASH_MD5:    return "md5";
    case EOS_HASH_SHA1:   return "sha1";
    case EOS_HASH_SHA224: return "sha224";
    case EOS_HASH_SHA256: return "sha256";
    case EOS_HASH_SHA384: return "sha384";
    case EOS_HASH_SHA512: return "sha512";
    default: return NULL;
  }
}

int eos_hash_init(eos_hash_ctx_t *ctx, eos_hash_alg_t alg) {
  size_t dsz = eos_hash_digest_size(alg);
  if (!ctx || dsz == 0) return -1;
  memset(ctx, 0, sizeof(*ctx));
  ctx->alg = alg;
  ctx->digest_size = (uint32_t)dsz;
  ctx->block_size = (alg == EOS_HASH_SHA384 || alg == EOS_HASH_SHA512) ? 128u : 64u;
  switch (alg) {
    case EOS_HASH_MD5:
      ctx->state.w32[0] = 0x67452301u; ctx->state.w32[1] = 0xefcdab89u;
      ctx->state.w32[2] = 0x98badcfeu; ctx->state.w32[3] = 0x10325476u;
      break;
    case EOS_HASH_SHA1:
      ctx->state.w32[0] = 0x67452301u; ctx->state.w32[1] = 0xefcdab89u;
      ctx->state.w32[2] = 0x98badcfeu; ctx->state.w32[3] = 0x10325476u;
      ctx->state.w32[4] = 0xc3d2e1f0u;
      break;
    case EOS_HASH_SHA224: memcpy(ctx->state.w32, sha224_init, sizeof(sha224_init)); break;
    case EOS_HASH_SHA256: memcpy(ctx->state.w32, sha256_init, sizeof(sha256_init)); break;
    case EOS_HASH_SHA384: memcpy(ctx->state.w64, sha384_init, sizeof(sha384_init)); break;
    case EOS_HASH_SHA512: memcpy(ctx->state.w64, sha512_init, sizeof(sha512_init)); break;
    default: return -1;
  }
  return 0;
}

void eos_hash_update(eos_hash_ctx_t *ctx, const void *data, size_t len) {
  const uint8_t *p = (const uint8_t *)data;
  if (!ctx || !p || len == 0) return;
  ctx->total += len;
  if (ctx->buf_len) {
    size_t take = ctx->block_size - ctx->buf_len;
    if (take > len) take = len;
    memcpy(ctx->buf + ctx->buf_len, p, take);
    ctx->buf_len += (uint32_t)take;
    p += take;
    len -= take;
    if (ctx->buf_len < ctx->block_size) return;
    hash_block(ctx, ctx->buf);
    ctx->buf_len = 0;
  }
  while (len >= ctx->block_size) {
    hash_block(ctx, p);
    p += ctx->block_size;
    len -= ctx->block_size;
  }
  if (len) {
    memcpy(ctx->buf, p, len);
    ctx->buf_len = (uint32_t)len;
  }
}

void eos_hash_final(eos_hash_ctx_t *ctx, uint8_t *out) {
  if (!ctx || !out) return;
  const uint32_t bs = ctx->block_size;
  const uint32_t len_bytes = (bs == 128u) ? 16u : 8u;
  const uint64_t bits_lo = ctx->total << 3;
  const uint64_t bits_hi = ctx->total >> 61;

  ctx->buf[ctx->buf_len++] = 0x80;
  if (ctx->buf_len > bs - len_bytes) {
    memset(ctx->buf + ctx->buf_len, 0, bs - ctx->buf_len);
    hash_block(ctx, ctx->buf);
    ctx->buf_len = 0;
  }
  memset(ctx->buf + ctx->buf_len, 0, bs - len_bytes - ctx->buf_len);
  if (ctx->alg == EOS_HASH_MD5) {
    store_le64(ctx->buf + bs - 8, bits_lo);
  } else if (bs == 64u) {
    store_be64(ctx->buf + 56, bits_lo);
  } else {
    store_be64(ctx->buf + 112, bits_hi);
    store_be64(ctx->buf + 120, bits_lo);
  }
  hash_block(ctx, ctx->buf);

  uint8_t full[64];
  if (ctx->alg == EOS_HASH_MD5) {
    for (int i = 0; i < 4; i++) store_le32(full + 4 * i, ctx->state.w32[i]);
  } else if (bs == 64u) {
    for (int i = 0; i < 8; i++) store_be32(full + 4 * i, ctx->state.w32[i]);
  } else {
    for (int i = 0; i < 8; i++) store_be64(full + 8 * i, ctx->state.w64[i]);
  }
  memcpy(out, full, ctx->digest_size);
  memset(full, 0, sizeof(full));
  memset(ctx, 0, sizeof(*ctx));
}

void eos_hash_buf(eos_hash_alg_t alg, const void *data, size_t len, uint8_t *out) {
  eos_hash_ctx_t ctx;
  if (eos_hash_init(&ctx, alg) != 0) return;
  eos_hash_update(&ctx, data, len);
  eos_hash_final(&ctx, out);
}

///////////////////////////////////////////////////////////////////////
// Hex and comparison helpers
///////////////////////////////////////////////////////////////////////
void eos_hash_to_hex(const uint8_t *digest, size_t len, char *out) {
  static const char hex[] = "0123456789abcdef";
  for (size_t i = 0; i < len; i++) {
    out[2 * i] = hex[digest[i] >> 4];
    out[2 * i + 1] = hex[digest[i] & 15];
  }
  out[2 * len] = '\0';
}

static int hex_val(char c) {
  if (c >= '0' && c <= '9') return c - '0';
  if (c >= 'a' && c <= 'f') return c - 'a' + 10;
  if (c >= 'A' && c <= 'F') return c - 'A' + 10;
  return -1;
}

int eos_hash_from_hex(const char *hex, size_t hex_len, uint8_t *out, size_t out_cap) {
  if (!hex || !out || (hex_len & 1u) || hex_len / 2 > out_cap) return -1;
  for (size_t i = 0; i < hex_len / 2; i++) {
    int hi = hex_val(hex[2 * i]);
    int lo = hex_val(hex[2 * i + 1]);
    if (hi < 0 || lo < 0) return -1;
    out[i] = (uint8_t)((hi << 4) | lo);
  }
  return (int)(hex_len / 2);
}

bool eos_hash_equal(const uint8_t *a, const uint8_t *b, size_t len) {
  uint8_t diff = 0;
  for (size_t i = 0; i < len; i++) diff |= (uint8_t)(a[i] ^ b[i]);
  return diff == 0;
}

///////////////////////////////////////////////////////////////////////
// CRC-32 (IEEE) and POSIX cksum
///////////////////////////////////////////////////////////////////////
uint32_t eos_crc32(uint32_t crc, const void *data, size_t len) {
  const uint8_t *p = (const uint8_t *)data;
  crc = ~crc;
  for (size_t i = 0; i < len; i++) {
    crc ^= p[i];
    crc = (crc >> 4) ^ crc32_nibble[crc & 15u];
    crc = (crc >> 4) ^ crc32_nibble[crc & 15u];
  }
  return ~crc;
}

uint32_t eos_cksum_update(uint32_t crc, const void *data, size_t len) {
  const uint8_t *p = (const uint8_t *)data;
  for (size_t i = 0; i < len; i++) {
    crc = (crc << 4) ^ cksum_nibble[(crc >> 28) ^ (p[i] >> 4)];
    crc = (crc << 4) ^ cksum_nibble[(crc >> 28) ^ (p[i] & 15u)];
  }
  return crc;
}

uint32_t eos_cksum_final(uint32_t crc, uint64_t total_len) {
  while (total_len) {
    uint8_t b = (uint8_t)(total_len & 0xFFu);
    crc = eos_cksum_update(crc, &b, 1);
    total_len >>= 8;
  }
  return ~crc;
}
